const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const root = path.join(__dirname, '..');
const manifest = JSON.parse(fs.readFileSync(path.join(root, 'manifest.json'), 'utf8'));
const source = file => fs.readFileSync(path.join(root, file), 'utf8');
const tick = () => new Promise(resolve => setImmediate(resolve));

test('MAIN and ISOLATED resources never reuse a URL; generated page bundle is current', () => {
  const entries = manifest.content_scripts.filter(entry => entry.matches.includes('https://testcase.ac/*'));
  const mainFiles = entries.filter(entry => entry.world === 'MAIN').flatMap(entry => entry.js);
  const isolatedFiles = entries.filter(entry => entry.world !== 'MAIN').flatMap(entry => entry.js);
  assert.deepEqual(mainFiles.filter(file => isolatedFiles.includes(file)), []);
  const expected = '// Generated by node scripts/build-testcase-bridge.js. Edit protocol.js / bridge.js instead.\n' +
    ['scripts/testcase/protocol.js', 'scripts/testcase/bridge.js'].map(file => source(file).replace(/\r\n/g, '\n').trimEnd()).join('\n\n') + '\n';
  assert.equal(source('scripts/testcase/page-bridge.js').replace(/\r\n/g, '\n'), expected);
});

test('shared helpers register on each world global, including separate script scopes and reinjection', () => {
  const worlds = [vm.createContext({}), vm.createContext({})];
  for (const context of worlds) {
    for (let count = 0; count < 2; count++) {
      // Do not inject mocks for the protocol: exercise the real registration code.
      vm.runInContext(`(function(){${source('scripts/testcase/protocol.js')}\n})();`, context);
      vm.runInContext(`(function(){${source('scripts/archive/links.js')}\n})();`, context);
    }
    assert.equal(typeof context.BJHTestcase?.accepted, 'function');
    assert.equal(typeof context.BJHArchive?.archiveUrl, 'function');
  }
  assert.notEqual(worlds[0].BJHTestcase, worlds[1].BJHTestcase);
});

test('actual manifest bundles in separate MAIN/ISOLATED worlds upload final passing result', async () => {
  const finalResult = { status: 'not_found', totalCases: 100, correctCasesCount: 100,
    wrongCasesCount: 0, executionFailedCasesCount: 0, requestId: 'test-run' };
  const code = '#include <iostream>\nint main(){int a,b;std::cin>>a>>b;std::cout<<a+b;}';
  const location = { hostname: 'testcase.ac', origin: 'https://testcase.ac',
    href: 'https://testcase.ac/problems/boj/1000', pathname: '/problems/boj/1000' };
  const store = { isSync: true, bjhEnable: true, BaekjoonHub_token: 'test-token',
    BaekjoonHub_hook: 'test-owner/test-repo', stats: { version: manifest.version, branches: {}, submission: {} } };
  const panels = new Map(), requests = [], errors = [], blobs = [];
  let messageListener;
  function element() {
    return { style: {}, setAttribute() {}, addEventListener() {},
      appendChild(child) { if (child.id) panels.set(child.id, child); } };
  }
  const document = { documentElement: {}, body: element(), createElement: element,
    getElementById: id => panels.get(id), querySelectorAll: () => [],
    querySelector: () => ({ textContent: 'A+B' }) };
  const isolated = vm.createContext({ document, location, URL, TextEncoder, btoa,
    TextDecoder, Request, Response, setTimeout: () => 0, clearTimeout() {}, AbortSignal,
    console: { log() {}, error: (...args) => errors.push(args) },
    MutationObserver: class { observe() {} },
    addEventListener: (_, fn) => { messageListener = fn; },
    chrome: { runtime: { getManifest: () => manifest, sendMessage: async () => ({ level: 1 }) },
      storage: { local: {
        get: (key, cb) => cb({ [key]: store[key] === undefined ? undefined : structuredClone(store[key]) }),
        set: (data, cb) => { Object.assign(store, structuredClone(data)); cb?.(); },
      } } },
    fetch: async (url, init = {}) => {
      const method = init.method || 'GET';
      const body = init.body ? JSON.parse(init.body) : null;
      requests.push({ url, method, body });
      let result;
      if (url.includes('/contents/')) return new Response('{}', { status: 404 });
      if (method === 'GET' && url.endsWith('/test-owner/test-repo')) result = { default_branch: 'main' };
      else if (method === 'GET' && url.endsWith('/git/ref/heads/main')) result = { ref: 'refs/heads/main', object: { sha: 'parent' } };
      else if (method === 'POST' && url.endsWith('/git/blobs')) { blobs.push(body); result = { sha: `blob-${blobs.length}` }; }
      else if (method === 'POST' && url.endsWith('/git/trees')) result = { sha: 'tree-1' };
      else if (method === 'POST' && url.endsWith('/git/commits')) result = { sha: 'commit-1' };
      else if (method === 'PATCH' && url.endsWith('/git/refs/heads/main')) result = {};
      else throw new Error(`Unexpected GitHub request: ${method} ${url}`);
      return new Response(JSON.stringify(result));
    },
  });
  isolated.window = isolated;
  const isolatedWindow = vm.runInContext('window', isolated);
  const main = vm.createContext({ document, location, URL, TextDecoder, Request,
    fetch: async () => new Response(JSON.stringify({ type: 'result', result: finalResult })),
    postMessage: (data, origin) => { setImmediate(() => {
      Promise.resolve(messageListener({ data: structuredClone(data), origin, source: isolatedWindow })).catch(error => errors.push(error));
    }); },
  });
  main.window = main;
  const injectedFiles = new Set();
  for (const entry of manifest.content_scripts.filter(entry => entry.matches.includes('https://testcase.ac/*'))) {
    const context = entry.world === 'MAIN' ? main : isolated;
    for (const file of entry.js) {
      // Exercise loading even when injection is deduplicated by resource URL.
      if (injectedFiles.has(file)) continue;
      injectedFiles.add(file);
      vm.runInContext(source(file), context, { filename: file });
    }
  }
  assert.equal(typeof main.BJHTestcase, 'object');
  assert.equal(typeof isolated.BJHTestcase, 'object');
  const response = await main.fetch('https://api.testcase.ac/api/problems/boj/1000/stress', {
    method: 'POST', body: JSON.stringify({ targetCode: code, targetCodeLang: 'cpp23' }),
  });
  assert.deepEqual((await response.json()).result, finalResult);
  for (let attempt = 0; attempt < 50 && !panels.get('bjh-testcase-status')?.textContent?.includes('업로드 완료'); attempt++) await tick();
  assert.deepEqual(errors, []);
  assert.match(panels.get('bjh-testcase-status')?.textContent || '', /GitHub 업로드 완료/);
  assert.equal(blobs.length, 2);
  assert.equal(Buffer.from(blobs[0].content, 'base64').toString('utf8'), code);
  assert.match(Buffer.from(blobs[1].content, 'base64').toString('utf8'), /100\/100/);
  assert.equal(requests.filter(request => request.url.endsWith('/git/commits')).length, 1);
  const head = requests.find(request => request.method === 'PATCH');
  assert.equal(head.body.force, false);
  assert.equal(store.stats.branches['test-owner/test-repo'], 'main');
});
